#include <stdio.h>
int main() {
    int i, sum = 0;
    for (i = 0; i < 1000000; i++) {
        sum += i * i;
    }
    printf("Sum: %d\n", sum);
    return 0;
}

void matrix_multiply(float A[100][100], float B[100][100], float C[100][100]) {
    for (int i = 0; i < 100; i++)
        for (int j = 0; j < 100; j++)
            C[i][j] = A[i][j] * B[i][j]; // 99%时间消耗在此行
}
